  /// UTF-8, not NUL-terminated on the wire.


  factory Result.decode(Uint8List bytes, [int offset = 0]) {
    if (bytes.length - offset < 5) {
      throw RangeError('truncated result header');
    }
    final n = bytes[offset + 4];
    if (n > 59 || bytes.length - offset < 5 + n) {
      throw RangeError('bad len in result');
    }
    final available = bytes.length - offset;
    final limit = available < 5 + n ? available : 5 + n;
    final bd = ByteData.sublistView(bytes, offset, offset + limit);
    return Result(
        ver: bd.getUint8(0),
        op: bd.getUint8(1),
        opId: bd.getUint8(2),
        status: bd.getUint8(3),
        len: n,
        detail: _readString(bytes, offset + 5, n),
    );
  }

  Uint8List encode() {
    final detailBytes = _encodeString(detail, 59);
    final out = Uint8List(5 + detailBytes.length);
    final bd = ByteData.sublistView(out);
    bd.setUint8(0, 1);
    bd.setUint8(1, op);
    bd.setUint8(2, opId);
    bd.setUint8(3, status);
    bd.setUint8(4, detailBytes.length);
    out.setRange(5, 5 + detailBytes.length, detailBytes);
    return out;
  }
}

