/// config — 80 bytes, fixed.
class Config {
  Config({
    this.ver = 0,
    this.units = 0,
    this.displayTimeoutS = 0,
    this.deviceName = '',
    this.billowsTargetF10 = 0,
    this.billowsMode = 0,
    List<int>? reserved0,
  }) : reserved0 = reserved0 ?? List<int>.filled(57, 0);

  static const int size = 80;
  static const int maxSize = 80;

  final int ver;
  final int units;
  final int displayTimeoutS;
  /// 0 = never; otherwise 30/60/120.
  final String deviceName;
  /// UTF-8, NUL-padded, <=15 chars.
  final int billowsTargetF10;
  /// Reserved; ignored/unwritten in the MVP.
  final int billowsMode;
  /// Must be 0 (observe) in the MVP.
  final List<int> reserved0;


  factory Config.decode(Uint8List bytes, [int offset = 0]) {
    if (bytes.length - offset < size) {
      throw RangeError('truncated config');
    }
    final bd = ByteData.sublistView(bytes, offset, offset + size);
    return Config(
        ver: bd.getUint8(0),
        units: bd.getUint8(1),
        displayTimeoutS: bd.getUint16(2, Endian.little),
        deviceName: _readString(bytes, offset + 4, 16),
        billowsTargetF10: bd.getInt16(20, Endian.little),
        billowsMode: bd.getUint8(22),
        reserved0: [for (var i = 0; i < 57; i++) bd.getUint8(23 + i * 1)],
    );
  }

  Uint8List encode() {
    final out = Uint8List(size);
    final bd = ByteData.sublistView(out);
    bd.setUint8(0, 1);
    bd.setUint8(1, units);
    bd.setUint16(2, displayTimeoutS, Endian.little);
    _writeString(out, 4, 16, deviceName);
    bd.setInt16(20, billowsTargetF10, Endian.little);
    bd.setUint8(22, billowsMode);
    bd.setUint8(23, 0);
    return out;
  }
}

/// stats — 60 bytes, fixed.
class Stats {
  Stats({
    this.ver = 0,
    this.flags = 0,
    this.uptimeS = 0,
    this.recordsStored = 0,
    this.recordsCapacity = 0,
    this.minSeq = 0,
    this.maxSeq = 0,
    this.generation = 0,
    this.packetsOk = 0,
    this.packetsBad = 0,
    this.batteryMv = 0,
    this.batteryPct = 0,
    this.loraRssi = 0,
    this.loraSnr = 0,
    this.reserved0 = 0,
    this.heapFree = 0,
    this.heapMin = 0,
    this.droppedSamples = 0,
    this.reserved1 = 0,
    this.oldestUnixS = 0,
    this.newestUnixS = 0,
  });

  static const int size = 60;
  static const int maxSize = 60;

  final int ver;
  final int flags;
  final int uptimeS;
  final int recordsStored;
  final int recordsCapacity;
  final int minSeq;
  /// SEQ_NONE if empty.
  final int maxSeq;
  /// SEQ_NONE if empty.
  final int generation;
  final int packetsOk;
  final int packetsBad;
  final int batteryMv;
  final int batteryPct;
  /// 255 = unknown.
  final int loraRssi;
  final int loraSnr;
  final int reserved0;
  final int heapFree;
  final int heapMin;
  final int droppedSamples;
  final int reserved1;
  final int oldestUnixS;
  /// 0 if unknown.
  final int newestUnixS;
  /// 0 if unknown.

  bool get smokePaired => (flags & (1 << 0)) != 0;
  bool get smokeLive => (flags & (1 << 1)) != 0;
  bool get advertising => (flags & (1 << 2)) != 0;
  bool get connected => (flags & (1 << 3)) != 0;
  bool get clockValid => (flags & (1 << 4)) != 0;
  bool get storageOk => (flags & (1 << 5)) != 0;
  bool get billowsAttached => (flags & (1 << 6)) != 0;
  bool get billowsControl => (flags & (1 << 7)) != 0;

  factory Stats.decode(Uint8List bytes, [int offset = 0]) {
    if (bytes.length - offset < size) {
      throw RangeError('truncated stats');
    }
    final bd = ByteData.sublistView(bytes, offset, offset + size);
    return Stats(
        ver: bd.getUint8(0),
        flags: bd.getUint8(1),
        uptimeS: bd.getUint32(2, Endian.little),
        recordsStored: bd.getUint32(6, Endian.little),
        recordsCapacity: bd.getUint32(10, Endian.little),
        minSeq: bd.getUint32(14, Endian.little),
        maxSeq: bd.getUint32(18, Endian.little),
        generation: bd.getUint32(22, Endian.little),
        packetsOk: bd.getUint32(26, Endian.little),
        packetsBad: bd.getUint32(30, Endian.little),
        batteryMv: bd.getUint16(34, Endian.little),
        batteryPct: bd.getUint8(36),
        loraRssi: bd.getInt8(37),
        loraSnr: bd.getInt8(38),
        reserved0: bd.getUint8(39),
        heapFree: bd.getUint32(40, Endian.little),
        heapMin: bd.getUint32(44, Endian.little),
        droppedSamples: bd.getUint16(48, Endian.little),
        reserved1: bd.getUint16(50, Endian.little),
        oldestUnixS: bd.getUint32(52, Endian.little),
        newestUnixS: bd.getUint32(56, Endian.little),
    );
  }

  Uint8List encode() {
    final out = Uint8List(size);
    final bd = ByteData.sublistView(out);
    bd.setUint8(0, 1);
    bd.setUint8(1, flags);
    bd.setUint32(2, uptimeS, Endian.little);
    bd.setUint32(6, recordsStored, Endian.little);
    bd.setUint32(10, recordsCapacity, Endian.little);
    bd.setUint32(14, minSeq, Endian.little);
    bd.setUint32(18, maxSeq, Endian.little);
    bd.setUint32(22, generation, Endian.little);
    bd.setUint32(26, packetsOk, Endian.little);
    bd.setUint32(30, packetsBad, Endian.little);
    bd.setUint16(34, batteryMv, Endian.little);
    bd.setUint8(36, batteryPct);
    bd.setInt8(37, loraRssi);
    bd.setInt8(38, loraSnr);
    bd.setUint8(39, 0);
    bd.setUint32(40, heapFree, Endian.little);
    bd.setUint32(44, heapMin, Endian.little);
    bd.setUint16(48, droppedSamples, Endian.little);
    bd.setUint8(50, 0);
    bd.setUint32(52, oldestUnixS, Endian.little);
    bd.setUint32(56, newestUnixS, Endian.little);
    return out;
  }
}

