  /// Clamped 0-255.
  final int reserved0;

  bool get smokePaired => (flags & (1 << 0)) != 0;
  bool get smokeLive => (flags & (1 << 1)) != 0;
  bool get billowsAttached => (flags & (1 << 2)) != 0;
  bool get billowsOutput => (flags & (1 << 3)) != 0;
